class T:
    def __init__(self):
        self._d = 0
    @property
    def f(self):
        return self._d * 2
    @property
    def d(self):
        return self._d
    @d.setter
    def d(self, v):
        if v < 0:
            raise ValueError
        self._d = v
t = T()
t.d = 3
assert t.d == 3
assert t.f == 6
try:
    t.d = -1
except ValueError:
    pass
else:
    assert False

class R:
    def __init__(self, w, h):
        self.w = w
        self.h = h
    @property
    def area(self):
        return self.w * self.h
r = R(2, 3)
assert r.area == 6
r.w = 5
assert r.area == 15

calls = []
class T:
    @property
    def d(self):
        return self._d
    @d.setter
    def d(self, v):
        calls.append(v)
        if v < 0:
            raise ValueError
        self._d = v
